/* Intermediate6: standard on-demand Event Functions; bounded runtime model. */
(function () {
  const N=AG.aws.n,REGION='ap-south-1',JOBS='arn:aws:sqs:ap-south-1:123456789012:photo-jobs',FAILURES='arn:aws:sqs:ap-south-1:123456789012:photo-failures';
  const SVG='<svg xmlns="http://www.w3.org/2000/svg" width="320" height="240" viewBox="0 0 320 240"><rect width="320" height="240" fill="red"/></svg>';
  const EVENT=()=>({Records:[{eventSource:'aws:s3',s3:{bucket:{name:'shop-uploads'},object:{key:'uploads/kurta.svg',versionId:'v-photo'}}}]});
  const DEST=()=>({OnFailure:{Destination:FAILURES}}),file=x=>({content:JSON.stringify(x,null,2)}),clone=x=>JSON.parse(JSON.stringify(x));
  const table=s=>'<div class="tbl-wrap">'+s+'</div><p class="muted">Phone par baaki columns dekhne ke liye table ko side mein swipe karo.</p>';
  function seed(){return {region:REGION,lambdaConcurrencyQuota:1000,
    lambdas:[{name:'photo-resize',runtime:'python3.12',handler:'app.handler',roleName:'shop-lambda',state:'Active',lastUpdateStatus:'Successful',memory:128,timeout:3,architectures:['x86_64'],reservedConcurrency:2,busyConcurrent:2,revisionId:'r0',workload:{kind:'svg-fixture',sourceBucket:'shop-uploads',outputBucket:'shop-thumbs',sourceKey:'uploads/kurta.svg',baseMs:800,ioFloorMs:300,initMs:300}},{name:'courier-webhook',runtime:'python3.12',handler:'webhook.handler',state:'Active',memory:256,timeout:10,invokeResult:'{"accepted":true}'}],
    roles:[{name:'shop-lambda',lambda:{trust:'lambda.amazonaws.com',sourceBucket:'shop-uploads',outputBucket:'shop-thumbs',receiveQueues:[JOBS],sendQueues:[FAILURES]}}],
    buckets:[{name:'shop-uploads',region:REGION,public:false,encryption:true,versioning:true,versions:{'uploads/kurta.svg':[{versionId:'v-photo',body:SVG,size:SVG.length,storageClass:'STANDARD',deleteMarker:false}]}},{name:'shop-thumbs',region:REGION,public:false,encryption:true,objects:[]}],
    queues:[{name:'photo-jobs',arn:JOBS,url:'https://sqs.ap-south-1.amazonaws.com/123456789012/photo-jobs',visibilityTimeout:120,isFifo:false,messages:[]},{name:'photo-failures',arn:FAILURES,url:'https://sqs.ap-south-1.amazonaws.com/123456789012/photo-failures',visibilityTimeout:120,isFifo:false,messages:[]}],eventSourceMappings:[],
    logGroups:[{name:'/aws/lambda/photo-resize',events:['fixture-request-old Task timed out after 3.00 seconds','TooManyRequestsException: ReservedFunctionConcurrentInvocationLimitExceeded; configured reserve 2']}]
  };}
  const fn=s=>(s.account.lambdas||[]).find(f=>f.name==='photo-resize');
  function capacity(s){const f=fn(s);return !!f&&!f.pendingConfig&&f.memory>=512&&f.memory<=2048&&f.timeout>=15&&f.timeout<=30&&f.state==='Active'&&AG.lambdaTiming(f).warmMs+AG.lambdaTiming(f).initMs<=2000&&f.reservedConcurrency>=10&&f.reservedConcurrency<=20&&Math.ceil(10*AG.lambdaTiming(f).warmMs/1000)<=f.reservedConcurrency;}
  function asyncReady(s){const f=fn(s),c=f&&f.asyncConfigs&&f.asyncConfigs.$LATEST;return !!c&&c.MaximumRetryAttempts===2&&c.MaximumEventAgeInSeconds===3600&&c.DestinationConfig&&c.DestinationConfig.OnFailure&&c.DestinationConfig.OnFailure.Destination===FAILURES;}
  function mappingReady(s){const rows=(s.account.eventSourceMappings||[]).filter(m=>m.functionName==='photo-resize');return rows.length===1&&rows[0].eventSourceArn===JOBS&&rows[0].batchSize===10&&rows[0].state==='Enabled'&&!rows[0].pendingState&&rows[0].responseTypes.length===1&&rows[0].responseTypes[0]==='ReportBatchItemFailures';}
  function derivatives(s){const b=(s.account.buckets||[]).find(b=>b.name==='shop-thumbs'),rows=b&&b.objects;return Array.isArray(rows)&&rows.length===3&&[64,128,256].every(size=>rows.some(o=>o.sourceVersion==='v-photo'&&o.width===size&&o.height===size&&o.body===SVG.replace('width="320"','width="'+size+'"').replace('height="240"','height="'+size+'"')));}
  function preserved(s){const a=seed(),f=fn(s),src=(s.account.buckets||[]).find(b=>b.name==='shop-uploads'),versions=src&&src.versions&&src.versions['uploads/kurta.svg'];return !!f&&f.runtime==='python3.12'&&f.handler==='app.handler'&&f.roleName==='shop-lambda'&&(s.account.lambdas||[]).length===2&&JSON.stringify(s.account.lambdas.find(f=>f.name==='courier-webhook'))===JSON.stringify(a.lambdas[1])&&(s.account.buckets||[]).length===2&&s.account.buckets.every(b=>!b.public&&b.encryption)&&Array.isArray(versions)&&versions[0].versionId==='v-photo'&&versions[0].body===SVG&&!versions[0].deleteMarker&&src.versioning&&JSON.stringify(s.account.roles)===JSON.stringify(a.roles)&&JSON.stringify(s.account.queues)===JSON.stringify(a.queues);}
  function invokeProof(s,out){const f=fn(s),r=s.downloads&&s.downloads[out];return !!f&&!!r&&!r.error&&r.functionName===f.name&&r.revisionId===(f.revisionId||'r0')&&r.executedVersion==='$LATEST';}
  const SOLUTION=[
    'aws lambda update-function-configuration --function-name photo-resize --memory-size 1024 --timeout 15',
    'aws lambda wait function-updated-v2 --function-name photo-resize',
    'aws lambda put-function-concurrency --function-name photo-resize --reserved-concurrent-executions 10',
    'aws lambda put-function-event-invoke-config --function-name photo-resize --maximum-retry-attempts 2 --maximum-event-age-in-seconds 3600 --destination-config file://destination.json',
    'aws lambda create-event-source-mapping --function-name photo-resize --event-source-arn '+JOBS+' --batch-size 10 --function-response-types ReportBatchItemFailures --enabled',
    'aws lambda list-event-source-mappings --function-name photo-resize',
    'aws lambda invoke --function-name photo-resize --cli-binary-format raw-in-base64-out --payload file://event.json invoke.json'
  ];
  const TASKS=[{text:'Model mein fixture p99 ≤2 s; memory 512..2048 MB, timeout 15..30 s, reserve 10..20 aur 10 RPS ki capacity',check:capacity},{text:'Purane function par async retry 2 / age 3600 s / pehle se bani failure queue',check:asyncReady},{text:'Ek hi Enabled jobs mapping, batch 10 aur ReportBatchItemFailures',check:mappingReady},{text:'Exact v-photo ki teen sahi copies (derivatives); asli source bacha raha',check:derivatives},{text:'invoke.json mein purane source version ke liye current-$LATEST ka safal result hai',check:s=>{const r=s.downloads&&s.downloads['invoke.json'],x=r&&r.body&&r.body.results;return invokeProof(s,'invoke.json')&&Array.isArray(x)&&x.length===1&&x[0].sourceVersion==='v-photo'&&x[0].written+x[0].duplicates===3;}},{text:'Purane functions, versioned input, private buckets, role aur khaali queues bache rahe',check:preserved}];
  function budget(k){const memory=[128,256,512,1024,2048,3072][k.memory],calls=[2e5,1e6,5e6,1e7][k.calls],slots=[0,2,10][k.pc],cold=[0,1,5,10][k.cold]/100;
    const m=AG.lambdaTiming({memory,workload:{baseMs:k.base,ioFloorMs:100,initMs:300}}),needed=Math.max(1,Math.ceil(10*m.warmMs/1000)),coverage=Math.min(1,slots/needed),remainingCold=cold*(1-coverage),p99=m.warmMs+(remainingCold>=0.01?m.initMs:0),gb=memory/1024;
    const arm=k.arch===1,onRate=arm?0.0000133334:0.0000166667,pcRate=arm?0.0000077778:0.0000097222,allocRate=arm?0.0000033334:0.0000041667;
    const on=calls*(1-coverage)*(m.warmMs+cold*m.initMs)/1000*gb*onRate,pcRun=calls*coverage*m.warmMs/1000*gb*pcRate,allocation=slots*gb*30*24*3600*allocRate,requests=calls/1e6*.20,total=on+pcRun+allocation+requests;
    return {memory,calls,slots,m,needed,p99,total,allocation,compute:on+pcRun,requests,ok:calls>=5e6&&k.base>=700&&cold>=0.01&&p99<=2000&&total*88<=7000};}
  function Q(q,correct,wrong,answer,explain, domain){const choices=wrong.slice();choices.splice(answer,0,correct);return {q,choices,answer,explain, domain};}
  AG.registerLevels('intermediate',[{
    id:'lambda',icon:'⚡',title:'Lambda + API Gateway: retries, limits aur output ka saboot',badge:'Serverless Sardar',
    objectives:['<b>Invocation:</b> sync, async aur poll karne wala event source mapping alag pehchano','<b>Performance:</b> timeout, memory/CPU, cold init aur concurrency ke controls','<b>HTTP:</b> API type/auth/timeout chuno; API keys login (authentication) nahi hain','<b>Sahi kaam:</b> exact source version, duplicate se safe outputs, partial batch response','<b>Kharcha:</b> billed duration, architecture aur paid provisioned capacity compare karo','<b>Saboot:</b> function error/body dekho; sirf HTTP 200 safalta nahi'],
    hook:{when:'SHOPKARO · SELLER PHOTOS + COURIER WEBHOOK · COURSE KI KAHANI (FICTIONAL)',title:'“Din ki 200 photos ke liye 24 ghante wala EC2, ya event aane par code?”',text:'Sellers product photos upload karte hain; ShopKaro ko har photo ke teen thumbnail size chahiye. Courier partner bhi status ka webhook bhejta hai. Ravi poore din chalne wala EC2 lagana chahta hai. Neha ko event par chalne wala processing chahiye, par duplicate events, badi photo ka timeout aur fail hui deliveries ka saaf plan bhi. Apne aap scale hona unlimited capacity nahi, aur business ka sahi kaam bhi apne aap nahi hota.'},
    steps:[
      {q:'Function, trigger aur execution environment ka simple model kya hai?',analogy:'Full-time electrician har ghante ki tankhwah leta hai. On-call electrician sirf call aane par kaam karta hai. Par auzaar ready karne ka time aur ek saath kitni calls le sakta hai, yeh phir bhi maayne rakhta hai.',body:'<p>Standard on-demand Lambda Event Function = code + set kiya runtime, execution role aur trigger. Servers AWS sambhalta hai; app ka code, dependencies, permissions, retries aur data ki sahi-galat tumhari zimmedari hai. Execution environment dobara use ho sakta hai; par reuse hoga hi, ya kitni der khaali rehne par, iski guarantee nahi.</p>',points:['S3 photo event ek chhota worker chala sakta hai; courier API turant jawaab (acknowledgement) de sakta hai. Lamba workflow aur pakki state ke liye alag design chahiye. Business ki state sirf process memory ya /tmp mein mat rakho.','Warm request pehle ki initialization dobara use karti hai; cold initialization runtime/dependencies/code load karti hai. Freeze/thaw se reuse aur naya environment banna alag events hain. "15 minute khaali raha toh hamesha cold" jaisa koi likha hua niyam nahi.','Course ka scope standard on-demand Event Functions hai. Aaj Lambda mein Managed Instances, durable/Web Function jaise models bhi hain, jinki limits alag hain; ek model ke quotas/daam har Lambda par mat lagao.'],asli:'Kaam: dry run ek upload hue source version ko init, execution, retry aur failure capture tak follow karta hai. Local lab handler ko laptop ke Python par chalata hai; app ka runtime ek saaf, chhota SVG fixture use karta hai.'},
      {q:'Sync, async aur event source mapping mein retry kiska kaam hai?',analogy:'Phone call mein caller line par rukta hai. Daak ke dabbe mein chitthi backend ki queue mein rukti hai. Courier collection mein worker queue se batch uthata hai. Har raaste mein failure ka zimmedar alag hai.',body:table('<table><tr><th>Raasta</th><th>Example</th><th>Failure ka zimmedar</th></tr><tr><td>Sync</td><td>API Gateway, seedha RequestResponse</td><td>Caller ko jawaab dikhta hai; retry caller ki policy</td></tr><tr><td>Async push</td><td>S3, SNS, EventBridge</td><td>Lambda ki andar wali queue, retry/age/destination</td></tr><tr><td>Poll-based mapping</td><td>SQS, Kinesis, DynamoDB Streams</td><td>Source/mapping ke apne batch/retry niyam</td></tr></table>'),points:['Async push mein function error par default se do extra attempts milte hain. Throttling/system errors backoff aur event-age ke hisaab se chalte hain (default 6 ghante tak). "Har error par bilkul do retries" galat hai. Bina error ke bhi duplicate delivery ho sakti hai.','SQS mein retries visibility/redrive aur handler ke batch response se chalti hain. ReportBatchItemFailures on karo aur fail hue message IDs lautao. Async function destinations SQS ki redrive policy ki jagah nahi lete.','SQS visibility kam se kam function timeout jitni honi chahiye; AWS kam se kam 6× timeout + batching window kehta hai. FIFO mein order ka dhyaan rakh kar partial failure sambhalna padta hai; yeh lab Standard SQS use karti hai.'],asli:'Kaam: terminal async failure capture aur SQS mapping dono set karta hai, kyunki ShopKaro do raaston se kaam leta hai. Haath se invoke handler ka result check karta hai; queue ka apne aap padha jaana model nahi hota.'},
      {q:'Timeout, payload, memory aur /tmp ki limits ka matlab kya hai?',code:'aws lambda get-function-configuration --function-name photo-resize\naws lambda update-function-configuration --function-name photo-resize --memory-size 1024 --timeout 15\naws lambda wait function-updated-v2 --function-name photo-resize',analogy:'Kaam ki deadline, parcel ka size, worker ke resources aur thodi der ki desk ki jagah: sab alag controls hain. Badi desk business data ko safe nahi banati; extra CPU I/O ke intezaar ko apne aap nahi sulajhata.',body:table('<table><tr><th>Standard on-demand scope</th><th>Aaj ki likhi hui value</th></tr><tr><td>Execution timeout</td><td>1..900 second</td></tr><tr><td>Memory / temporary storage</td><td>128..10,240 MB / 512..10,240 MB</td></tr><tr><td>Buffered sync request/response</td><td>6 MB har ek</td></tr><tr><td>Async payload</td><td>October 2025 se 1 MB</td></tr><tr><td>Streamed sync response</td><td>200 MB tak; bandwidth ke niyam alag</td></tr></table>'),points:['Memory badhane se CPU bhi badhta hai; speed aur kharcha workload ka benchmark tay karta hai. "4× memory hamesha 4× tez" ki koi guarantee nahi. I/O ka intezaar, dependencies aur aage ki limits zyada bhaari pad sakti hain.','Deployment ZIP ka size, layers, container image ka size aur invocation payload alag-alag quotas hain. Aaj standard ZIP ki uncompressed limit layers milakar 250 MB hai; image ki limit 10 GB. Supported runtimes aur architecture ke saath chalne wali dependencies use karo.','/tmp thodi der ka hai, environment reuse hone par bacha bhi reh sakta hai; data ke pakka rehne ka koi vaada nahi. 512 MB se zyada temporary storage ka alag charge hai. Aaj Managed Instances eligible async/ESM invocations ko 90 minute tak chala sakte hain; standard on-demand function ka timeout 15 minute hi hai.'],asli:'Kaam: tune karne se pehle memory/timeout aur asli error body dekho. Bada timeout dheeme code ko chhupa deta hai, jab tak latency ka target aur aage ki concurrency bhi fit na ho.'},
      {q:'Reserved aur provisioned concurrency mein farak kya hai?',code:'aws lambda get-function-concurrency --function-name photo-resize\naws lambda put-function-concurrency --function-name photo-resize --reserved-concurrent-executions 10',analogy:'Reserved capacity matlab restaurant ki 10 seats sirf tumhare group ke liye rakhi hain. Provisioned matlab un seats par staff aur table pehle se taiyaar hai. Seat reserve karne se garam khana milne ki guarantee nahi.',body:'<p>Concurrency = ek saath chal rahe kaam, lagbhag aane ki rate × chalne ka time. Aam taur par region mein default 1,000 shared concurrent executions hote hain, par naye accounts mein kam quota ho sakta hai. Function ke scale hone ki speed aur aage ke systems bhi throughput ko rokte hain.</p>',points:['Reserved concurrency sirf is function ke liye capacity rakhta hai aur maximum limit bhi lagata hai; iska alag charge nahi. Reserved 0 function ko throttle kar deta hai. Account ka zaroori unreserved pool bachao; reserve environments ko pehle se taiyaar nahi karta.','Provisioned concurrency published version ya alias par pehle se taiyaar environments deta hai, aur iska allocation aur execution ka alag daam hai. $LATEST par PC nahi chalta. Taiyaar capacity se zyada requests on-demand cold starts mein chali ja sakti hain.','10 RPS × 0.8 s = lagbhag 8 concurrent executions, safety aur upar-neeche hone se pehle. DB/partner ki limits bachane ke liye cap lagao, phir ConcurrentExecutions, Throttles, Duration aur aage ki health dekho. Concurrency aur requests/second ek hi unit nahi.'],asli:'Kaam: course fixture reserve 2 aur do busy requests se shuru hota hai. Reserve 10 karo, phir right-size karke dikhao ki 10 RPS ki capacity aur latency fit hain. Bahut bada cap chun lena aage ke budget ko poora nahi karta.'},
      {q:'Cold start kam karne ke tareeke kya hain? VPC ko aankh band karke kyun na hataayein?',analogy:'Electrician ka toolkit halka karna, tagda worker dena, pehle se taiyaar station rakhna, ya taiyaar snapshot se shuru karna: alag-alag tareeke hain. Private warehouse chahiye, toh wahan ka raasta theek karo; warehouse ki zaroorat hi mat mitao.',body:'<p>Initialization ko handler execution se alag naapo. Startup/package ka bekaar kaam kam karo, memory/CPU aur architecture ka benchmark lo, safe clients dobara use karo, aur supported SnapStart/provisioned concurrency ko asli latency aur kharche se compare karo.</p>',points:['Aaj SnapStart Java 11+, Python 3.12+, .NET 8+ aur unke supported image formats par chalta hai. Published version ke snapshot restore mein unique values aur connections refresh karne ki shartein hain; support/Region/runtime check karo. SnapStart har jagah free nahi.','Aaj ke docs ke hisaab se SnapStart provisioned concurrency, EFS/S3Files ya 512 MB se zyada /tmp ke saath nahi chalta. PC taiyaar capacity ke andar cold init kam karta hai; lifecycle resets, spillover, aage ki latency aur handler failures phir bhi rehte hain.','VPC access ka koi pakka +100 ms penalty nahi. Private DB tak pahunchne wale function ko sahi VPC config chahiye. Public subnet mein lagane se function ko public IP nahi milta; internet ke liye sahi NAT/IPv6 raasta chahiye, ya supported AWS APIs ke liye service endpoints.'],asli:'Kaam: planner ke latency numbers CPU/IO ka course model hain, AWS benchmark nahi. Asli production faisle ke liye naapi hui cold/warm distributions aur concurrency/load test chahiye.'},
      {q:'HTTP API, REST API, WebSocket ya function URL?',analogy:'Courier ko simple doorbell chahiye, ya protocol/auth/policies wala poora reception desk? Endpoint ka type business ke contract se chuno. Ek API key kisi employee ka pehchaan badge nahi hai.',body:table('<table><tr><th>Choice</th><th>Kab use</th><th>Review</th></tr><tr><td>HTTP API</td><td>Simple HTTP routing, JWT/IAM/Lambda authorizer</td><td>Features ka set; integration timeout 30 s</td></tr><tr><td>REST API</td><td>Usage plans/keys, kuch advanced API controls</td><td>API keys login nahi hain; extra kharcha/features</td></tr><tr><td>WebSocket API</td><td>Dono taraf message bhejne wala connection</td><td>Connection sambhalna, auth aur message limits</td></tr><tr><td>Function URL</td><td>Function ka simple seedha HTTPS endpoint</td><td>IAM/NONE + resource permissions; gateway wale controls kam</td></tr></table>'),points:['API Gateway ka account level default kai regions mein 10,000 RPS hai; kuch likhe hue regions mein 2,500 RPS. Throttle/burst limits DDoS ka poora ilaaj nahi, na har customer ka pakka billing limit. API type/features, WAF/Shield ka design aur login alag faisle hain.','REST regional/private integration ka default timeout 29 s hai; quota aur trade-off ki manzoori se badh sakta hai; edge-optimized 29 s hi rehta hai. HTTP API mein maximum 30 s. Lambe kaam wali API aksar turant "mil gaya" bol kar kaam queue mein daalti hai aur status alag se dikhati hai, request ko khula pakad kar nahi rakhti.','October 2025 se naye function URLs ke liye lambda:InvokeFunctionUrl aur lambda:InvokeFunction dono permissions chahiye. AWS_IAM signed, allowed access use karta hai; NONE ke liye resource policy soch-samajh kar review karo. Courier callbacks mein replay/idempotency aur request asli hai ya nahi, yeh check bhi chahiye.'],asli:'Kaam: zaroorat ke hisaab se endpoint aur auth chuno. Terminal event worker ko theek karta hai; koi nakli API Gateway deployment ya HTTP network ka saboot nahi diya jaata.'},
      {q:'Memory badhane se bill kab ghatega, kab badhega?',analogy:'Tez worker ka ghante ka rate zyada ho sakta hai, par kaam jaldi khatam ho toh kul kharcha utna hi ya kam ho sakta hai. Khaali baithe taiyaar staff ka bill alag hai.',body:'<p>Standard on-demand ka kul example: 50 lakh calls × 0.5 GB × 0.2 s = 5,00,000 GB-seconds. US East x86 pehle tier ka lagbhag rate $0.0000166667/GB-s se $8.33 duration + $1 chhote payload wali requests. Asli INIT/extensions, API Gateway, logs, S3, network aur baaki charges aur jodte hain.</p>',points:['Aaj pehle tier mein arm64 duration lagbhag $0.0000133334/GB-s hai, x86 $0.0000166667; architecture ke saath chalna aur speed ka benchmark lo, koi fixed tezi mat maano. Daam US East 2025–26 ke examples hain, har region ke nahi. Hisaab ke liye ₹88 = $1.','INIT ka time bill hota hai. Khaali on-demand function par execution duration nahi judti, par provisioned concurrency, storage/log/network resources aur baaki services ka kharcha phir bhi lag sakta hai. "Poora serverless stack khaali hai toh $0" jaisa koi vaada nahi.','PC mein taiyaar GB-seconds ka allocation charge + PC execution aur request charges lagte hain; spillover on-demand rate par jaata hai. Planner free tier/credits, discounts, PC recycle INIT aur aage ke kharche nahi jodta; yeh kul andaaza hai, bill nahi.','Maane hue $20/mahina ke hamesha chalte compute se break-even sirf workload ka hisaab hai. EC2/Fargate ko operations, capacity, availability, load balancing aur network ka budget bhi chahiye; barabar zarooraton par compare karo.'],asli:'Kaam: planner mein kam se kam 50 lakh invocations aur bataya hua workload rakho. p99 poora kiye bina memory ka bill kam karna sahi optimization nahi.'},
      {q:'Retries ke saath data sahi hai, iska asli saboot kya hai?',analogy:'Courier ek hi parcel ki receipt do baar de sakta hai. Receipt ki key se duplicate pehchano, parcel ka asli version padho, aur pehle se rakhe parcel ka saamaan check karo. Sirf "request mil gayi" ki mohar aakhri delivery nahi hai.',body:'<p>Event ya business ki ek pakki pehchaan use karo, aur data store par aisa operation jo dobara chalne par bhi galat na kare (idempotent). Local SVG lab outputs ko source bucket/key/version se key karti hai aur conditional create se likhti hai. Duplicate delivery pehle se bane bytes compare karti hai; galat derivative mile toh saaf fail hota hai.</p>',points:['Late event ke process hone se pehle source key par nayi file aa sakti hai. Exact source VersionId se purane event ke liye galti se nayi photo nahi padhi jaati. S3 event ki keys URL-encoded hoti hain; space/plus sahi se decode karo.','Alag output bucket, ya review kiya input-prefix filter, baar-baar khud ko trigger karne wale loop ko rokta hai. Recursive loop detection kuch hi service/SDK raaston par kaam karta hai; yeh loop se bachne aur kharche/backlog par nazar rakhne ki jagah nahi.','Galti jo sab karte hain: dobara chalne par nuksaan karne wale kaam ko retry karna, HTTP 200 ko handler ki safalta maanna, partial-batch flag on karke IDs na lautana, ya output se hi input dobara trigger hone dena.','Production mein aisa hota hai: duplicate ya ulte order ke events, aadha likhne ke baad timeout, pehle ka kharab output, zehreele (poison) messages aur quota khatam. Kaam ke failure records, DLQ/replay tools, monitoring aur dobara process karne ka ek owner rakho. Interview ke sawaal: retry kaun karta hai? Kaunsa exact source version? Aadhe likhe derivatives ke baad kya hota hai?'],asli:'Kaam: app mein invoke.json ki body aur source/output ki state match honi chahiye. Laptop ka handler test asli local S3 bytes aur ek saath aaye duplicates check karta hai; dono test deployed AWS ya Docker runtime prove nahi karte.'},
    ],
    myth:[
      {myth:'“15 minute khaali raha, toh cold start pakka hai.”',sach:'Khaali rehne ka koi fixed timer contract nahi. Environment reuse, init aur cold start runtime/workload/lifecycle par depend karte hain.'},
      {myth:'“Reserved concurrency garam (warm) environments khareedti hai.”',sach:'Reserved sirf is function ki capacity aur cap set karta hai. Provisioned concurrency qualified environments pehle se taiyaar karta hai aur uska alag daam hai.'},
      {myth:'“StatusCode 200 matlab worker ne sahi output bana diya.”',sach:'Invoke 200 ke saath FunctionError bhi de sakta hai. Response body aur asli output/version ka saboot dekho; DryRun ya async 202 ka matlab kaam poora nahi.'},
      {myth:'“Serverless matlab bina limit ka scale aur poore stack ka khaali bill zero.”',sach:'Quotas, scale hone ki speed, aage ki limits aur paid resources rehte hain. Function ka time, taiyaar capacity, API/log/storage/network ke charges alag hain.'},
    ],
    playbook:{title:'Function ya hamesha chalta compute: faisle ka guide',use:['Event par chalne wale chhote standard Lambda kaam, saaf retry/idempotency contract ke saath','Simple HTTP controls ke liye HTTP API; REST/WebSocket/URL tab jab asli feature ki zaroorat ho','Naap kar memory/architecture tune karo; aage ke systems bachane ke liye reserved cap'],avoid:['Business ki state sirf process memory ya /tmp mein','Lambe kaam ko synchronous HTTP deadline ke peeche rakhna, bina review kiye async design ke','Bina limit ke retries, input/output ka ek hi trigger raasta, ya maanna ki API keys callers ki pehchaan karti hain'],how:['Sync/async/poller ka raasta aur retry ka zimmedar likho','Payload, deadline, concurrency aur aage ke budget set karo; cold/warm distribution ka benchmark lo','Pakka input version/business ID, conditional writes aur scoped failure records use karo','Function error/body ke saath asli data aur deployed delivery ka saboot dekho'],redflags:['Cold start ki fixed der ya VPC penalty ko guarantee bolna','Har invocation type/error par do retries ka daava','ReportBatchItemFailures flag on, par failed IDs ka response nahi','$LATEST par provisioned concurrency, ya spillover ka kharcha bhoolna'],rule:'Kaam ka contract → invocation/retry ka zimmedar → resource/latency limits → idempotency/failure capture → poora kharcha aur asli output ka saboot.'},
    exam:[
      {cue:'"short event-driven workload; least server management"',pick:'Standard Lambda candidate',why:'Quotas, dependencies aur aage ki zarooratein check karo; apne aap scale hona bhi limit mein hai.'},
      {cue:'"standard job exceeds 15 minutes"',pick:'Fargate/Batch/EC2 ya koi doosra supported compute model dekho',why:'Standard timeout 900 s; aaj ke eligible Managed Instances wale exceptions ka scope alag hai.'},
      {cue:'"cap downstream concurrency / protect other functions"',pick:'Reserved concurrency',why:'Capacity ko alag rakhna aur cap; pehle se garam karna nahi.'},
      {cue:'"strict cold-start latency target"',pick:'Provisioned concurrency / supported SnapStart compare karo',why:'Published version/alias, compatibility, spillover aur paid resources maayne rakhte hain.'},
      {cue:'"SQS batch has only some failed records"',pick:'ReportBatchItemFailures + sahi failed IDs',why:'Source ki visibility/redrive async function destinations se alag hai.'},
      {cue:'"capture exhausted async events"',pick:'Review kiya async OnFailure destination ya DLQ',why:'Role ki permissions aur event-age/retry ka behaviour invocation ke raaste se match hona chahiye.'},
      {cue:'"VPC function needs public internet"',pick:'Sahi egress route/NAT ya supported IPv6 design',why:'Sirf public subnet se function ko public IP nahi milta; AWS endpoints kuch services ka access dete hain.'},
      {cue:'"usage plans/API keys"',pick:'API Gateway REST API ka feature wala faisla',why:'API key login nahi hai; sahi IAM/authorizer/authentication use karo.'},
      {cue:'"duplicate S3 events / overwritten source key"',pick:'Pakki pehchaan, exact VersionId aur idempotent output',why:'Exactly-once delivery ya HTTP success status par bharosa mat karo.'},
    ],
    stages:[
      {type:'dryrun',title:'🔬 Photo event: init, timeout, retry aur duplicate',goal:'Har step par invocation ka zimmedar aur output ka saboot pehchano; teen faislon ka jawaab do.',
        nodes:[N('s3#source',150,100,{label:'Input version'}),N('lambda',490,100,{label:'Worker'}),N('s3#output',820,100,{label:'Derivatives'}),N('sqs#retry',490,300,{label:'Lambda queue',icon:'⏳'}),N('sqs#failure',820,440,{label:'Failure record'}),N('cloudwatch',150,440,{label:'Logs / metrics'})],
        edges:[{from:'s3#source',to:'lambda'},{from:'lambda',to:'s3#output'},{from:'lambda',to:'sqs#retry'},{from:'sqs#retry',to:'lambda'},{from:'sqs#retry',to:'sqs#failure'},{from:'lambda',to:'cloudwatch'}],
        panels:[{id:'attempt',title:'Execution / delivery'},{id:'data',title:'Source / output'}],
        steps:[
          {clock:'upload',say:'Version wali photo aati hai. S3 ek async event bhejta hai, URL-encoded key aur VersionId ke saath. Event accept hone ka matlab yeh nahi ki derivatives ban gaye.',flows:[{from:'s3#source',to:'lambda',tone:'busy',label:'async event'}],panels:{attempt:['Cold environment ko INIT chahiye ho sakta hai','Standard worker shuru mein 128 MB / timeout 3 s'],data:['Input: uploads/kurta.svg / v-photo','Output bucket input se alag']}},
          {clock:'INIT',say:'Fixture ko initialization + CPU/IO ka kaam chahiye. Kam memory par model ka execution timeout se lamba ho jaata hai. Koi fixed khaali-time contract ya VPC ka pakka penalty nahi maana gaya.',nodes:{lambda:{tone:'slow',badge:'deadline risk'}},ask:{q:'Performance ka pehla kaam ka saboot kya hai?',choices:['Memory ya capacity badalne se pehle timeout, init/handler ka time aur workload ka profile dekho','Maan lo har VPC fixed der jodta hai, phir bina zaroorat dekhe private database ka access hata do','Reserved concurrency set karo aur maan lo ki reservation har request ke liye garam environments taiyaar karta hai'],answer:0,explain:'Failure kis stage par hai aur resource settings naapo. VPC penalty aur reserved se pehle garam hone wale daave galat hain.'}},
          {clock:'timeout',say:'Function error async retry tak pahunchta hai. Default function-error policy do extra attempts deti hai. Throttle/system errors ka backoff/age alag hai; asli source version waisa hi rehta hai.',flows:[{from:'lambda',to:'sqs#retry',tone:'bad',label:'function error'}],panels:{attempt:['Attempt1 fails','Function-error retries: default se 2 extra tak','Duplicates remain possible'],data:['Aadhe likhe outputs ho sakte hain','Pakka source version aur output keys use karo']}},
          {clock:'retry',say:'Kuch derivatives banne ke baad ek duplicate event aata hai. Conditional create + byte check sahi outputs bachata hai aur jo missing hain unhe bharta hai.',ask:{q:'Galat duplicate kaam se kaise bachein?',choices:['Latest key padho aur purane event ki pehchaan dobara use karo, kyunki source overwrite ka alag dhyaan nahi chahiye','Source version ki pehchaan use karo, outputs conditional create karo aur pehle bane derivative ke bytes check karo','Process ke baad source versions delete karo, taaki duplicate delivery asli input data tak pahunch hi na sake'],answer:1,explain:'Pakki pehchaan aur exact version ka read late events ko bachata hai. Latest key lene se nayi upload process ho sakti hai; delete karne se source ka saboot kho jaata hai.'},flows:[{from:'sqs#retry',to:'lambda',tone:'busy',label:'replay safely'}]},
          {clock:'exhaustion',say:'Agar event ke errors set kiye retries khatam kar dein ya event ki age nikal jaaye, toh review kiya OnFailure destination invocation ka record pakad leta hai. SQS poll wale raaste ka visibility/redrive alag hai.',flows:[{from:'sqs#retry',to:'sqs#failure',tone:'bad',label:'capture failure'}],panels:{attempt:['Async retry/age/destination saaf set kiye gaye','SQS mapping ka partial response ek alag contract hai'],data:['Failure record ko permission aur ek owner chahiye','Asli error samajhne ke baad replay karo']}},
          {clock:'repair',say:'Sahi size ka worker aur sahi concurrency seedhe payload test mein pass hote hain; source version aur teeno derivative bodies match karti hain. Output input ke trigger raaste se bahar rehta hai.',nodes:{lambda:{tone:'ok',badge:'output verified'},'s3#output':{tone:'ok',badge:'3 sizes'}},flows:[{from:'lambda',to:'s3#output',tone:'ok',label:'preserve original'}],ask:{q:'Agar outputs usi input prefix ko trigger karein, toh kya maayne rakhta hai?',choices:['Recursive detection ko poora bachav maano aur maan lo ki unsupported raaste paid loops nahi banate','Reserved concurrency badhao taaki loop khaali ho jaaye, aur wahi output-trigger config chalu rehne do','Output/filter ke raaste alag rakho aur backlog par nazar rakho; recursive detection kuch hi raaste cover karta hai'],answer:2,explain:'Loop se bachna sabse pehla kaam hai. Loop detection har raasta cover nahi karta, na kharcha hataata hai; zyada concurrency loop ko aur bada kar sakti hai.'}},
        ],lesson:'Async accept hona, handler ka chalna aur sahi derivative bytes: teen alag steps hain. Retry ka zimmedar aur event ki pehchaan raaste se match honi chahiye.'},
      {type:'flowlab',title:'🎛️ Memory, p99 aur paid taiyaar capacity',goal:'Mahine ki kam se kam 50 lakh calls rakho, 1 GB par workload ka base ≥700 ms aur dekha gaya cold share ≥1%. Model ka p99 ≤2 s, aur mahine ka kul budget ≤₹7,000. Workload/calls kam karke ya zero cold events bol kar jeet nahi milegi.',
        scenario:'Yeh poore desh ke scale ki alag planning exercise hai, din ki 200 photos ka aaj ka bill nahi. CPU/IO ka course model, AWS benchmark nahi: floor 100 ms, CPU ka hissa memory^0.8 ke saath badalta hai, 1 GB par INIT 300 ms aur memory ka sqrt asar. Peak 10 RPS, mahina 30 din; PC ke 2/10 slots poore mahine allocated, peak demand ka lagbhag coverage. x86/arm ki speed model mein barabar, US East ke aaj ke rates alag. Chhota payload = ek billed request; free tier/credits/discounts nahi. PC recycle INIT, API Gateway/S3/logs/network/extra storage/tax bahar. Daam ki table lesson mein hai; ₹88 = $1.',
        knobs:[{id:'memory',label:'Function memory',min:0,max:5,step:1,value:0,labels:{0:'128 MB',1:'256 MB',2:'512 MB',3:'1,024 MB',4:'2,048 MB',5:'3,072 MB'}},{id:'base',label:'1 GB par workload ka time',min:100,max:900,step:200,value:900,unit:' ms'},{id:'calls',label:'Monthly invocations',min:0,max:3,step:1,value:2,labels:{0:'200,000',1:'1 million',2:'5 million',3:'10 million'}},{id:'arch',label:'Architecture',min:0,max:1,step:1,value:0,labels:{0:'x86_64',1:'arm64'}},{id:'pc',label:'Taiyaar slots (poora mahina)',min:0,max:2,step:1,value:0,labels:{0:'0 / on-demand',1:'2 / provisioned',2:'10 / provisioned'}},{id:'cold',label:'On-demand cold share',min:0,max:3,step:1,value:2,labels:{0:'0%',1:'1%',2:'5%',3:'10%'}}],
        model:k=>{const b=budget(k);return {readouts:[{label:'Modeled warm / INIT',value:b.m.warmMs+' / '+b.m.initMs+' ms',tone:'info'},{label:'Modeled p99',value:b.p99+' ms',tone:b.p99<=2000?'ok':'bad'},{label:'Peak concurrent environments',value:b.needed+' at 10 RPS',tone:'info'},{label:'Approx execution + requests',value:'$'+b.compute.toFixed(2)+' + $'+b.requests.toFixed(2)+'/month',tone:'info'},{label:'Approx PC allocation',value:'$'+b.allocation.toFixed(2)+'/month',tone:b.allocation?'slow':'info'},{label:'Approx total / month',value:'$'+b.total.toFixed(2)+' / ₹'+Math.round(b.total*88).toLocaleString('en-IN'),tone:b.total*88<=7000?'ok':'bad'}],verdict:{ok:b.ok,text:b.ok?'Workload, model ki latency aur kul budget pass. Taiyaar capacity khareedne se pehle asli distributions/throughput naapo.':'Try karo: memory 1,024 MB, base 900 ms, 50 lakh calls, x86, PC 0, cold 5%. Zyada memory model ka time kam kar sakti hai; extra PC ka allocation aur execution ka kharcha hai.'}};},check:k=>budget(k).ok,
        lesson:'Optimization mein zaroori kaam bacha rehta hai. Memory CPU badalti hai; PC ka kharcha allocation, qualified execution aur spillover par depend karta hai. Architecture ki speed aur p99 naapne padte hain, ratte hue ratios se nahi.'},
      {type:'bins',title:'🗂️ Invocation ka raasta aur retry ka zimmedar',instructions:'Source ka invocation contract pehchano; sirf services ke naam kaafi nahi, likha hua integration raasta padho.',bins:[{id:'sync',label:'Sync caller waits'},{id:'async',label:'Async push queue'},{id:'poll',label:'Event source mapping'}],items:[
        {text:'API Gateway proxy HTTP jawaab ke liye standard function chalata hai',bin:'sync',explain:'Caller ke saamne sync integration; HTTP timeout aur caller ka retry maayne rakhte hain.'},{text:'S3 object-created notification seedha Lambda ko bhejta hai',bin:'async',explain:'S3 async push; duplicate se safe processing aur failure capture.'},{text:'Lambda Standard SQS queue ko batches mein poll karta hai',bin:'poll',explain:'ESM + visibility/redrive aur partial response ka contract.'},{text:'Handler ke result ke liye seedha Invoke RequestResponse',bin:'sync',explain:'FunctionError aur response body dekho, sirf status nahi.'},{text:'SNS topic ka notification seedha Lambda ko deta hai',bin:'async',explain:'Async function queue ka kaam; source service ka delivery behaviour bhi maayne rakhta hai.'},{text:'Lambda changes ke liye DynamoDB Streams poll karta hai',bin:'poll',explain:'Stream ka apna mapping behaviour; SQS ke retry niyam aankh band karke mat lagao.'},{text:'EventBridge rule ka target ek standard Lambda function hai',bin:'async',explain:'Async invocation; source ki delivery aur Lambda processing ki failure boundaries alag.'},{text:'Function URL ka client HTTPS jawaab ka intezaar karta hai',bin:'sync',explain:'Seedha HTTP contract, set kiye auth/resource permissions ke saath.'}]},
      {type:'match',title:'🔗 Control ka asli kaam',instructions:'Har control ko uske sahi kaam se jodo.',pairs:[
        {left:'Reserved concurrency',right:'Sirf is function ki capacity aur maximum cap; pehle se garam nahi karta',explain:'Capacity/aage ke systems bachao; reserved 0 throttle kar deta hai.'},{left:'Provisioned concurrency',right:'Pehle se taiyaar qualified environments, paid allocation ke saath',explain:'Published version/alias; spillover aur runtime behaviour phir bhi maayne rakhte hain.'},{left:'ReportBatchItemFailures',right:'ESM option + handler ka failed-ID response',explain:'Sirf flag se sahi batch handling nahi ban jaati.'},{left:'Async OnFailure destination',right:'Retry/age khatam hone ke baad invocation record',explain:'Permission aur replay chalane ka owner chahiye.'},{left:'Source VersionId',right:'Late event processing ke liye exact asli object',explain:'Latest key event ke source se nayi ho sakti hai.'},{left:'API key',right:'Usage-plan ki pehchaan, caller ka login nahi',explain:'Sahi IAM/JWT/authorizer/authentication alag se lagao.'}]},
      {type:'triage',title:'🩺 Thumbnails gayab: timeout aur throttle alag failures hain',symptom:'Course fixture mein purane timeout logs aur chalu load hai. Execution role pehle se exact source/output ka access deta hai. Worker memory 128 MB, timeout 3 s, reserve 2. S3 par ilzaam lagane se pehle config samjho.',commands:[
        {cmd:'aws logs tail /aws/lambda/photo-resize',out:'fixture-request-old Task timed out after 3.00 seconds\nTooManyRequestsException: ReservedFunctionConcurrentInvocationLimitExceeded',clue:true,note:'Execution deadline ki failure aur andar aane (admission) ka throttle alag hain.'},{cmd:'aws lambda get-function-configuration --function-name photo-resize',out:'{"MemorySize":128,"Timeout":3,"State":"Active","LastUpdateStatus":"Successful"}',clue:true,note:'Kam memory ka benchmark aur chhoti deadline review karni hai.'},{cmd:'aws lambda get-function-concurrency --function-name photo-resize',out:'{"ReservedConcurrentExecutions":2}',clue:true,note:'Sirf do concurrent executions allowed; pehle se garam nahi karta.'},{cmd:'aws iam list-roles',out:'{"Roles":[{"RoleName":"shop-lambda","Arn":"arn:aws:iam::123456789012:role/shop-lambda"}]}',clue:false,note:'Sirf role hone se policy prove nahi hoti, par yeh fixture review ki hui source/output policy deta hai.'}],questions:[
        Q('Dono dikhe hue error raaste kya batate hain?','Execution deadline/resource profile aur reserved admission capacity ko alag-alag review karo',['Sirf timeout badhao, kyunki throttle hui invocations pehle se handler ke andar chal rahi hain','Sirf S3 key badlo, kyunki admission throttle ka matlab hamesha source object gayab hai','$LATEST par provisioned slots khareedo, kyunki reserved capacity unhe apne aap garam kar deti hai'],0,'Timeout execution ke dauran hota hai; throttle andar aane/capacity ka hai. Sirf timeout cap theek nahi karta; missing key throttle nahi; PC ko qualified versions chahiye aur reserve pehle se garam nahi karta.'),
        Q('Kis repair ke baad output ka saboot bhi chahiye?','Benchmark se tune, update ka wait, sahi cap, phir body aur exact derivatives check karo',['Memory maximum kar do aur sirf update config ke status ko dekh kar safalta bol do','Function aur source versions delete karo, taaki purane timeout ka saboot dikhe hi nahi','Async retries band karo aur maan lo ki duplicate messages handler tak phir kabhi nahi aayenge'],1,'Capacity/latency tune karo, phir data check karo. Max memory ya status se kharcha ya output prove nahi hota; delete karne se saboot kho jaata hai; retries band karne se ek hi delivery pakki nahi hoti.')
      ]},
      {type:'terminal',title:'🖥️ Mission: worker theek karo aur source version ke outputs check karo',instructions:'Pehle ls/cat, function config/concurrency aur logs dekho. Saat steps; update aur mapping ke ready hone ka wait karo. Invoke ka response memory mein banta hai, laptop ki file nahi.',
        goal:'<ol><li>Purane <code>photo-resize</code> ko sahi size do: memory 512..2048 MB, timeout 15..30 s, model ka p99 ≤2 s.</li><li>Reserved cap 10..20 karo aur fixture ki 10 RPS capacity poori karo.</li><li>Async retries 2, maximum event age 3600 s, aur OnFailure queue <code>photo-failures</code> set karo.</li><li>Ek hi Enabled <code>photo-jobs</code> mapping rakho, batch 10 aur <code>ReportBatchItemFailures</code> ke saath.</li><li><code>event.json</code> se invoke karke <code>invoke.json</code> banao; current-$LATEST ki safal body aur v-photo ke teen exact derivatives check karo.</li></ol><p>Source version, private buckets, role, queues aur courier function bachao. Wait/list sirf fixture ko ready dikhata hai; asli runtime, time ya trigger delivery ka daava nahi.</p>',
        account:seed(),files:{'event.json':file(EVENT()),'destination.json':file(DEST()),'role-policy.json':file({Version:'2012-10-17',Statement:[{Effect:'Allow',Action:['s3:GetObject','s3:GetObjectVersion'],Resource:'arn:aws:s3:::shop-uploads/uploads/*'},{Effect:'Allow',Action:['s3:PutObject','s3:GetObject'],Resource:'arn:aws:s3:::shop-thumbs/thumbs/*'},{Effect:'Allow',Action:['sqs:ReceiveMessage','sqs:DeleteMessage','sqs:GetQueueAttributes'],Resource:JOBS},{Effect:'Allow',Action:'sqs:SendMessage',Resource:FAILURES}]})},tasks:TASKS,success:AG.allOf(TASKS),solution:SOLUTION,
        hints:SOLUTION.map((c,i)=>c+[' — benchmark ke hisaab se memory/deadline badlav maango',' — config ka wait karo; fixture poora hone se pehle purani settings rehti hain',' — capacity/cap reserve karo; yeh pehle se garam karna nahi',' — destination.json dekho; function ki async settings SQS retry se alag hain',' — jobs mapping aur handler ka partial-response contract set karo',' — fixture mein mapping ko Enabled hote dekho',' — aakhri payload/body/source-version check; sirf status 200 safalta nahi'][i]),
        successText:'Asli source version aur teeno derivative bodies match karti hain. Function ka aaj ka timing/capacity, async failure config aur mapping ka ready hona pass. Yeh ek chhota interpreter fixture hai; local lab alag se asli SVG handler chalati hai aur Moto S3 ke bytes check karti hai.'},
      {type:'docker',title:'🧪 Lab14: laptop par asli handler + Moto metadata',project:'14-lambda-handler-config',goal:'Asli trusted-SVG handler ke checks chalao, phir asli Lambda config ki CLI requests. Docker invocation abhi check nahi hua; runtime safal bolne ki jagah pakda gaya FunctionError dekho.',why:'Code ka seedha chalna, deployment metadata aur trigger/runtime delivery: teeno alag saboot dete hain.',steps:[
        {text:'Pehle se chalta Moto aur lab ka venv use karo. README dekho; apne aap install ya shared reset nahi.',cmd:'cd docker-labs && source env.sh && cd 14-lambda-handler-config',expect:'Loopback 4566 aur dummy test/test. Har metadata CLI service ka endpoint saaf likha hai.'},
        {text:'Laptop par trusted SVG handler aur bytes/duplicate/partial-batch checks chalao.',cmd:'../.venv/bin/python -I test_handler.py',expect:'19 checks; pehli baar 3 writes, dobara 0 writes/3 duplicates check hue; chaar ek saath deliveries mein 3 writes/9 duplicates; sirf bad-1 ka ID fail; purana exact version bacha; test buckets saaf.'},
        {text:'Controller padho, phir alag metadata resources banao aur asli CLI chalao.',cmd:'../.venv/bin/python -I lab.py setup && ../.venv/bin/python -I lab.py exercises',expect:'Memory 1024, Timeout 15, Update Successful; reserved 10, async config aur Enabled partial mapping. Invoke 200 mein Docker socket error ke saath FunctionError Handled aata hai; PC API 404.'},
        {text:'Sirf save kiye metadata resources saaf karo.',cmd:'../.venv/bin/python -I lab.py cleanup',expect:'Function aur lab ke buckets dhoondhne par do khaali arrays; koi shared reset nahi.'}
      ],observe:Q('Local lab ke do hisson ne kya pakka kiya?','Laptop ke handler ne check kiye SVG bytes likhe; Moto metadata Docker invocation prove nahi karta',['HTTP 200 ne prove kiya ki deployed Lambda safal chala, chahe FunctionError tha','Provisioned API 404 ne prove kiya ki taiyaar environments peeche ready the','Sirf Enabled mapping ka readback batata hai ki queue messages padhe gaye aur outputs pahunche'],2,'Laptop ke bytes/tests asli execution ka saboot hain. Invoke mein function error tha aur Docker nahi tha; PC 404 ka matlab support nahi; khaali queues/buckets delivery prove nahi karte.')},
      {type:'quiz',title:'🎓 Lambda + API choices',questions:[
        Q('Source key par nayi file aane ke baad S3 wahi event dobara bhejta hai. Input ka safe tareeka?','Event ka exact VersionId padho aur pakki, idempotent derivative keys use karo',['Jo bhi version latest hai woh padho, aur maan lo ki overwrite ke baad purane events nahi aate','Process se pehle purane versions delete karo, taaki duplicate deliveries ke paas padhne ko source na bache','S3 notifications ko exactly once maano aur saare conditional output checks chhod do'],3,'Exact version event ka matlab bachata hai. Latest nayi ho sakti hai; delete se saboot kho jaata hai; notifications duplicate ho sakte hain, isliye pakke conditional operations zaroori hain.', 'resilient'),
        Q('Reserved concurrency 10 mainly kya deta hai?','Function ke liye apni capacity aur cap, bina environments pehle se taiyaar kiye',['Das hamesha garam environments, har aane wali request par pakki latency ke saath','Har second das requests, chahe function ka time aur account ka throttling kuch bhi ho','Ek paid cache jo chalne se pehle dohraaye S3 event deliveries apne aap hata deta hai'],0,'Reserved concurrency chalti hui capacity ko alag rakhta aur cap karta hai. Na pehle se garam karta hai, na fixed RPS ke barabar hai, na events ka duplicate hataata hai.', 'high-performing'),
        Q('Seedha synchronous invoke 200 ke saath FunctionError lautata hai. Sahi matlab kya hai?','Invocation ka transport safal hua; safalta bolne se pehle function error body aur asli output dekho',['Function ne har business kaam poora kiya, kyunki HTTP 200 ka matlab exactly-once completion hai','Lambda har synchronous request ko wahi response lautane se pehle apne aap do baar retry karta hai','Sirf function ka timeout badhane se har missing object ya galat handler config theek ho jaayega'],1,'Status sirf invocation ke transport ka hai; FunctionError/body/data kaam ka result tay karte hain. Sync retry caller ka kaam hai; timeout har jagah ka ilaaj nahi.', 'resilient'),
        Q('SQS batch mein ek kharab record aur kai achhe records hain. Partial failure ka sahi contract?','ReportBatchItemFailures on karo aur sirf fail hue message IDs lautao; idempotency bhi rakho',['Function ka async retry 2 on karo aur source queue ki visibility/redrive settings poori hata do','Ek aam error string lautao aur maan lo ki mapping har achha record khud pehchaan lega','Poore batch ko acknowledge kar do, kyunki galat records ke saath bhi function ka HTTP status 200 hai'],2,'Mapping ka option aur handler ka failed-ID response, dono chahiye. SQS retry function ki async settings se alag hai; aam error poora batch dobara chala sakta hai, aur sab acknowledge karne se kharab records kho jaate hain.', 'resilient'),
        Q('Latency ke liye sensitive function ko provisioned concurrency chahiye. Kaunsa setup sahi hai?','Published version/alias use karo aur taiyaar allocation, execution aur spillover ka budget rakho',['Seedha $LATEST par set karo aur maan lo ki pehli initialization ke baad har request free hai','Sirf reserved concurrency set karo, kyunki reserved capacity aur warm-runtime ek hi service hai','SnapStart aur provisioned concurrency dono saath on karo, likhi hui compatibility review kiye bina'],3,'PC qualified hota hai aur bill hota hai; spillover rehta hai. $LATEST support nahi, reserve pehle se garam nahi karta, aur aaj SnapStart/PC saath nahi chalte.', 'high-performing'),
        Q('Private resource wale Lambda ko bahar ki public API tak jaana hai. Sahi salah kya hai?','VPC ki egress routing/NAT ya supported IPv6 design review karo; sirf subnet ka naam kaafi nahi',['Function ko public subnet mein le jao aur maan lo ki Lambda ko public instance IP apne aap mil jaata hai','Har VPC attachment hata do, kyunki har private database invocation par fixed 100 ms der lagti hai','S3 gateway endpoint banao aur maan lo ki har alag public internet API tak pahunch ho gayi'],0,'Network ka raasta maayne rakhta hai. Public subnet Lambda ko public IP nahi deta; VPC ki koi pakki der nahi; service endpoint kuch services cover karta hai, saara internet nahi.', 'high-performing'),
        Q('API ko usage plans/API keys chahiye. Kaunsi baat auth aur features ko saaf rakhti hai?','REST API ek option hai; API keys usage pehchanti hain, caller ke login ki jagah nahi leti',['HTTP API keys har caller ka login karti hain aur REST API ke saare usage-plan controls deti hain','Function URL NONE har public request par apne aap JWT pehchaan check jod deta hai','Throttling quota guarantee deta hai ki bina doosre controls ke har denial-of-service request ruk jaayegi'],1,'REST feature ki zaroorat chuno aur auth alag rakho. HTTP ke features alag hain, NONE JWT nahi jodta, aur quota throttling poora DDoS bachav nahi.', 'secure'),
        Q('Aaj ke standard on-demand Event Function ke payload/deadline ke baare mein sahi baat?', 'Standard timeout 900 s; buffered sync 6 MB har ek, async 1 MB; baaki Lambda models ka scope alag',['Buffered synchronous input 200 MB leta hai, kyunki streamed-response ka quota requests par bhi lagta hai','Async payload abhi bhi 256 KB hai aur har Lambda model ka invocation ceiling ek hi 900 second hai','API Gateway ka timeout badhane se standard Lambda ka maximum execution time apne aap badh jaata hai'],2,'Aaj ki standard limits aur scope maayne rakhte hain. Scaling ki limit hai; async 1 MB tak badha aur naye models alag hain; gateway ka timeout function ki limit nahi badalta.', 'high-performing')
      ]}
    ],
    interview:{title:'Interview: zimmedari, latency aur replay ka saboot',instructions:'Contract chuno; phir partial-batch config theek karo aur duplicate se safe response check karo.',questions:[
      Q('Interviewer: “Zyada memory hamesha paisa barbaad karti hai, ya hamesha chaar guna tez karti hai?”','Dono niyam galat; asli workload ke liye CPU/IO, latency aur GB-seconds ka benchmark lo',['Zyada memory hamesha kharcha badhati hai, kyunki billed time CPU aur workload se alag hai','Har baar memory double karne se speed double aur mahine ka bill bilkul same rehta hai','Memory initialization ya execution par kabhi asar nahi daalti, kyunki sabko same CPU milta hai'],3,'CPU badalta hai; asli workload ka time aur billed GB-seconds tay karte hain. Fixed speed/kharche ke daave I/O, init aur dependencies ko bhool jaate hain.', 'high-performing'),
      Q('Jawaab kho jaane par courier webhook dobara bhej sakta hai. Sahi kaam ki sabse zaroori shart?', 'Request asli hai ya nahi check karo, aur pakki pehchaan se business update ko idempotent banao',['Sirf API key ko login maano aur har duplicate delivery par business update chala do','Process hue events ka akela record process memory mein rakho, taaki har environment use share kare','Kaam pakka save karne se pehle success lauta do, aur maan lo ki jawaab khone par caller retry nahi karega'],0,'Request asli hona aur idempotency maayne rakhte hain. API keys login nahi; process memory share ya pakki nahi; jaldi "ho gaya" bolne se kaam kho sakta hai.', 'secure'),
      Q('Ek architecture mein Java/Python/.NET ki bhaari initialization hai. SnapStart par kya baat karein?', 'Aaj ka runtime/Region support, snapshot mein unique values ki safety aur compatibility/kharcha review karo',['Maan lo SnapStart hamesha sirf Java ke liye hai, images support nahi karta aur har runtime par free hai','SnapStart ko PC aur EFS ke saath milao, aaj ki koi support restriction review kiye bina','Har random identifier aur khule connection ka snapshot use karo, restore ke time koi check kiye bina'],1,'Aaj support badh gaya hai; unique values/connections aur limits phir bhi maayne rakhte hain. "Sirf Java/ZIP aur free" wale purane daave galat hain; PC/EFS ke combinations aur snapshot ki state review chahiye.', 'secure'),
      Q('Ek function S3 ke async events aur Standard SQS mapping dono se kaam leta hai. Retry config kaise ho?', 'Lambda async settings aur SQS visibility/redrive/partial responses ko alag contracts maano',['Function ka async retry 2 lagao aur maan lo ki har SQS message bilkul do receives ke baad delete hota hai','Sirf queue visibility use karo aur idempotency hata do, kyunki Standard SQS duplicates nahi deta','OnFailure destination ko source queue ke DLQ/redrive permissions ki har jagah wali jagah maano'],2,'Retry ka zimmedar alag hai. Function ki async settings SQS ke receives/delete tay nahi karti; Standard duplicate de sakta hai; destinations source queue ka redrive nahi badalte.', 'resilient'),
      {terminal:(()=>{const a=seed(),f=a.lambdas[0];f.memory=1024;f.timeout=15;f.reservedConcurrency=10;f.asyncConfigs={$LATEST:{MaximumRetryAttempts:2,MaximumEventAgeInSeconds:3600,DestinationConfig:DEST()}};
        a.eventSourceMappings=[{uuid:'11111111-1111-4111-8111-111111111111',functionName:'photo-resize',eventSourceArn:JOBS,batchSize:10,responseTypes:[],state:'Enabled'}];
        a.buckets[1].objects=[64,128,256].map(size=>({key:'thumbs/'+encodeURIComponent('shop-uploads/uploads/kurta.svg/v-photo')+'/'+size+'.svg',size:SVG.length,sourceVersion:'v-photo',width:size,height:size,body:SVG.replace('width="320"','width="'+size+'"').replace('height="240"','height="'+size+'"')}));
        const batch={Records:[{eventSource:'aws:sqs',messageId:'good-1',body:JSON.stringify(EVENT())},{eventSource:'aws:sqs',messageId:'bad-1',body:'invalid-json'}]},solution=['aws lambda update-event-source-mapping --uuid 11111111-1111-4111-8111-111111111111 --function-response-types ReportBatchItemFailures','aws lambda get-event-source-mapping --uuid 11111111-1111-4111-8111-111111111111','aws lambda invoke --function-name photo-resize --cli-binary-format raw-in-base64-out --payload file://batch.json batch-result.json'];
        const tasks=[...TASKS.filter((_,i)=>i!==4),{text:'Current batch ka safal result sirf bad-1 dikhata hai; achhe derivatives ka set waisa hi',check:s=>{const r=s.downloads&&s.downloads['batch-result.json'];return invokeProof(s,'batch-result.json')&&r.body&&JSON.stringify(r.body.batchItemFailures)===JSON.stringify([{itemIdentifier:'bad-1'}]);}}];
        return {title:'🖥️ Partial batch + duplicate se safe output',goal:'Config/timing aur sahi derivatives pehle se hain. Mapping mein partial-response option nahi hai. Purani mapping update karo, Enabled dekho, aur batch.json ko batch-result.json mein invoke karo. Sirf bad-1 fail hona chahiye; teeno asli derivatives bilkul waise hi rehne chahiye. Seedha payload test handler ka response contract prove karta hai, queue se asli delete ya apne aap delivery nahi.',account:a,files:{'batch.json':file(batch)},tasks,success:AG.allOf(tasks),solution,hints:solution.map((c,i)=>c+[' — duplicate banane ki jagah pehle wali mapping set karo',' — fixture mein mapping ka ready hona dekho',' — aakhri partial result aur na badle bytes ke checks'][i]),successText:'Partial response mein sirf bad-1 aata hai. Sahi derivative bodies waisi hi hain; source versions/role/queues bache rahe. Source poller ka acknowledgement aur asli deployed delivery ka alag runtime saboot abhi bhi chahiye.'};})()}
    ]},
    success:['Invocation ka raasta aur retry ka zimmedar pehchaan sakta hoon','Memory/timeout, reserved vs provisioned capacity aur cold init ka kharcha compare kar sakta hoon','Zaroorat ke hisaab se HTTP endpoint/auth/timeout ka chunav samjha sakta hoon','Exact version/idempotent output aur partial-batch ke sahi hone ka saboot check kar sakta hoon'],
    homework:'<p><b>Optional, sirf approved AWS sandbox mein (paisa lagega):</b> aaj ka function model aur Region quotas check karo; execution/INIT, API, logs, storage aur network ka budget rakho. Review kiya runtime/role aur versioned source deploy karo; output ka trigger raasta alag, event ki pakki pehchaan aur conditional writes. Asli source permission/filter set karo, aur async failure capture ya SQS visibility/redrive/partial-response contract. Ek chhota approved fixture upload karo; asli invocation logs, source version aur teeno output bytes dekho. Event dobara chalao aur ek failure simulate karo; check karo ki koi kharab duplicate output nahi bana aur failure ka kaam ka record hai. Courier endpoint mein request ka asli hona, idempotency aur supported auth/timeouts check karo. PC/SnapStart se pehle zaroori rate par cold/warm distribution ka benchmark lo; qualified version/alias aur aaj ke compatibility niyam use karo. Docker runtime wale hisse install aur network review hone tak unverified hain. Cleanup: source notifications/mappings, test PC, endpoints/API stages/log groups, exact temporary object versions, queues, function versions/aliases/role/policies; production/shared data aur rakhe gaye audit saboot bachao.</p>',
    cards:[{front:'Three invocation paths?',back:'Sync: caller rukta hai aur retry karta hai. Async push: function ki queue/retry/age. Poll mapping: source ke apne batch/retry niyam. "Har jagah do retry" jaisa koi niyam nahi.'},{front:'Reserved vs provisioned?',back:'Reserved concurrency ko alag aur cap karta hai, bina garam kiye. Provisioned published version/alias ke environments taiyaar rakhta hai, extra allocation/execution charge ke saath; spillover cold ho sakta hai.'},{front:'Current standard limits?',back:'Timeout 900 s, memory 128..10,240 MB, /tmp 512..10,240 MB. Buffered sync 6 MB har ek, async 1 MB; streamed response 200 MB alag. Baaki Lambda models ka scope alag.'},{front:'Cold start ka fixed khaali timer?',back:'Nahi. Init/handler ki distribution naapo; package/memory/architecture aur supported SnapStart/PC ka benchmark lo. VPC ka koi pakka penalty nahi.'},{front:'SQS partial batch?',back:'ReportBatchItemFailures on karo aur exact fail hue message IDs lautao. Idempotency, visibility/redrive aur FIFO order ki zarooratein alag rakho.'},{front:'Status200 proves success?',back:'Nahi. FunctionError, payload aur asli sahi data/version dekho. Async 202 sirf event accept karta hai; DryRun 204 handler chalata hi nahi.'},{front:'Recursive/duplicate kaam se kaise bachein?',back:'Alag output/filter, exact source version, pakke IDs aur byte check wale conditional writes. Recursive detection har jagah bachav ya kharche ki guarantee nahi deta.'},{front:'API key / function URL?',back:'API key usage ki pehchaan hai, login nahi. REST/HTTP/WebSocket/URL ke features alag hain. Naye function URLs ko aaj ke niyam mein InvokeFunctionUrl + InvokeFunction dono permissions chahiye.'}]
  }]);
})();
